-- Assessments. Apply after 010_content_management.sql. Safe to re-run; item data is upserted.
-- Generated by frontend/scripts/build-assessments.mts from scripts/assessment/*.json: edit those, then rebuild.
--
-- Answers are checked here, not in the browser:
-- - assessment_items holds each item's public prompt and, separately, the SHA-256 fingerprints
--   of the expected results plus the reference solution. No role can select it directly.
-- - The browser runs the learner's SQL/Python and saves only a fingerprint of what it produced.
-- - submit_assessment() compares fingerprints, scores the attempt, and only then returns the
--   reference solutions and explanations. The time limit is enforced with the server clock.

create table if not exists public.assessment_items (
  id text primary key check (id ~ '^as-(sql|py)-[0-9]{2,3}$'),
  kind text not null check (kind in ('sql', 'python')),
  title text not null,
  difficulty text not null check (difficulty in ('Easy', 'Medium', 'Hard')),
  topic text not null,
  prompt jsonb not null,
  answer jsonb not null,
  reference text not null,
  explanation text not null default '',
  active boolean not null default true
);
alter table public.assessment_items enable row level security;
-- Deliberately no policies: the items (answers included) are reachable only through the functions below.
revoke all on public.assessment_items from anon, authenticated;

create table if not exists public.assessment_attempts (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  config jsonb not null,
  items text[] not null,
  started_at timestamptz not null default now(),
  deadline timestamptz not null,
  submitted_at timestamptz,
  answers jsonb not null default '{}'::jsonb,
  results jsonb,
  score int,
  total int not null
);
create index if not exists assessment_attempts_user_idx on public.assessment_attempts (user_id, started_at desc);
alter table public.assessment_attempts enable row level security;
drop policy if exists assessment_attempts_read on public.assessment_attempts;
create policy assessment_attempts_read on public.assessment_attempts for select using (user_id = auth.uid() or public.is_admin());
-- No insert/update/delete policies: attempts change only through the functions below.

/** Public catalogue: prompts and counts, never answers. */
create or replace function public.assessment_catalog() returns table (id text, kind text, title text, difficulty text, topic text)
language sql stable security definer set search_path = public as $$
  select id, kind, title, difficulty, topic from assessment_items where active order by id;
$$;

/** Start an attempt: pick random active items for the config; returns the public prompts and the deadline. */
create or replace function public.start_assessment(p_kind text, p_difficulty text, p_topic text, p_count int, p_minutes int) returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  picked text[];
  att assessment_attempts;
begin
  if auth.uid() is null then raise exception 'sign in to take an assessment'; end if;
  if p_kind not in ('sql', 'python', 'mixed') then raise exception 'invalid kind'; end if;
  if p_count not between 1 and 10 or p_minutes not between 5 and 120 then raise exception 'invalid size or time limit'; end if;
  if (select count(*) from assessment_attempts where user_id = auth.uid() and started_at > now() - interval '1 hour') >= 20 then
    raise exception 'too many assessments started in the last hour';
  end if;
  select array_agg(id) into picked from (
    select id from assessment_items
    where active and (p_kind = 'mixed' or kind = p_kind)
      and (p_difficulty is null or p_difficulty = '' or difficulty = p_difficulty)
      and (p_topic is null or p_topic = '' or topic = p_topic)
    order by random() limit p_count) s;
  if picked is null then raise exception 'no assessment items match these settings'; end if;
  insert into assessment_attempts (user_id, config, items, deadline, total)
    values (auth.uid(), jsonb_build_object('kind', p_kind, 'difficulty', p_difficulty, 'topic', p_topic, 'count', p_count, 'minutes', p_minutes),
            picked, now() + make_interval(mins => p_minutes), cardinality(picked))
    returning * into att;
  return jsonb_build_object('id', att.id, 'started_at', att.started_at, 'deadline', att.deadline,
    'items', (select jsonb_agg(jsonb_build_object('id', i.id, 'kind', i.kind, 'title', i.title, 'difficulty', i.difficulty, 'topic', i.topic) || i.prompt order by array_position(picked, i.id))
              from assessment_items i where i.id = any(picked)));
end $$;

/** Save the fingerprint(s) of the learner's latest answer to one item. No correctness feedback. */
create or replace function public.save_assessment_answer(p_attempt uuid, p_item text, p_answer jsonb) returns text
language plpgsql volatile security definer set search_path = public as $$
declare att assessment_attempts;
begin
  select * into att from assessment_attempts where id = p_attempt and user_id = auth.uid() for update;
  if not found then raise exception 'attempt not found'; end if;
  if att.submitted_at is not null then raise exception 'attempt already submitted'; end if;
  if now() > att.deadline + interval '30 seconds' then raise exception 'time is up'; end if;
  if not (p_item = any(att.items)) then raise exception 'item not in this attempt'; end if;
  if pg_column_size(p_answer) > 4000 then raise exception 'answer too large'; end if;
  update assessment_attempts set answers = answers || jsonb_build_object(p_item, p_answer || jsonb_build_object('at', now())) where id = p_attempt;
  return 'saved';
end $$;

/** Score an attempt (also after the deadline) and return the results with references. */
create or replace function public.submit_assessment(p_attempt uuid) returns jsonb
language plpgsql volatile security definer set search_path = public as $$
declare
  att assessment_attempts;
  res jsonb := '[]'::jsonb;
  v_id text;
  v_item assessment_items;
  v_ans jsonb;
  v_ok boolean;
  v_passed int;
  v_cases int;
  v_score int := 0;
  v_out jsonb;
begin
  select * into att from assessment_attempts where id = p_attempt and user_id = auth.uid() for update;
  if not found then raise exception 'attempt not found'; end if;
  if att.submitted_at is not null then return att.results; end if;
  foreach v_id in array att.items loop
    select * into v_item from assessment_items where id = v_id;
    v_ans := att.answers -> v_id;
    if v_item.kind = 'sql' then
      v_ok := v_ans is not null and v_ans ->> 'sql' = v_item.answer ->> 'sql';
      v_passed := null; v_cases := null;
    else
      v_cases := jsonb_array_length(v_item.answer -> 'cases');
      select count(*) into v_passed from generate_series(0, v_cases - 1) i
        where v_ans is not null and v_ans -> 'cases' ->> i = v_item.answer -> 'cases' ->> i;
      v_ok := v_passed = v_cases;
    end if;
    if v_ok then v_score := v_score + 1; end if;
    res := res || jsonb_build_array(jsonb_build_object('id', v_id, 'passed', v_ok, 'answered', v_ans is not null,
      'cases_passed', v_passed, 'cases_total', v_cases, 'reference', v_item.reference, 'explanation', v_item.explanation));
  end loop;
  v_out := jsonb_build_object('id', att.id, 'score', v_score, 'total', att.total, 'started_at', att.started_at, 'submitted_at', now(), 'items', res);
  update assessment_attempts a set submitted_at = now(), score = v_score, results = v_out where a.id = p_attempt;
  return v_out;
end $$;

do $$
declare f text;
begin
  foreach f in array array['assessment_catalog()', 'start_assessment(text, text, text, int, int)', 'save_assessment_answer(uuid, text, jsonb)', 'submit_assessment(uuid)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;
grant execute on function public.assessment_catalog() to anon;
